            right[c] = i;
        }

        for (int q = 0; q < Q; q++) {
            char t = sc.next().charAt(0);
            char d = sc.next().charAt(0);
            int idx = t - 'a';

            if (left[idx] == -1) continue;

            if (d == 'L') {
                left[idx]++;
                if (left[idx] > right[idx]) {
                    left[idx] = -1;
                    right[idx] = -1;
                }
            } else { // 'R'
                right[idx]--;
                if (left[idx] > right[idx]) {
                    left[idx] = -1;
                    right[idx] = -1;
                }
            }

            // Now check if any other characters' ranges should be adjusted
            // because golems may have fallen off or shifted into other blocks
            // We just recompute boundaries for simplicity, since N, Q <= 200000
        }

        // We need to simulate properly: the above simple boundary update fails
        // because spells affect ALL golems on that character, not just edges.
        // Correct approach: track which positions still have golems.

        // Let's redo with a proper simulation using boolean array.
        boolean[] present = new boolean[N];
        Arrays.fill(present, true);

        for (int q = 0; q < Q; q++) {
            char t = sc.next().charAt(0);
            char d = sc.next().charAt(0);

            if (d == 'L') {
                for (int i = 0; i < N; i++) {
                    if (present[i] && s.charAt(i) == t) {
