                        else {
                            present[i] = false;
                            present[i-1] = true;
                        }
                    }
                }
            } else {
                for (int i = N-1; i >= 0; i--) {
                    if (present[i] && s.charAt(i) == t) {
                        if (i == N-1) present[i] = false;
                        else {
