    static char[] squares;
    static int N;
    static char[] spellChar;
    static char[] spellDir;
    static int Q;

    // Returns: -1 if fell left, 1 if fell right, 0 if survived
    static int simulate(int start) {
        int pos = start;
        for (int i = 0; i < Q; i++) {
            if (squares[pos - 1] == spellChar[i]) {
                if (spellDir[i] == 'L') pos--;
                else pos++;
            }
            if (pos == 0) return -1;
            if (pos == N + 1) return 1;
        }
        return 0;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        N = Integer.parseInt(br.readLine().trim());
        squares = br.readLine().trim().toCharArray();
        Q = Integer.parseInt(br.readLine().trim());
        spellChar = new char[Q];
        spellDir = new char[Q];
        for (int i = 0; i < Q; i++) {
            String line = br.readLine().trim();
            spellChar[i] = line.charAt(0);
            spellDir[i] = line.charAt(2);
        }

        // Find largest L such that golem starting at L falls off left
        int lo = 0, hi = N;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (simulate(mid) == -1) lo = mid;
            else hi = mid - 1;
        }
        int leftBound = lo; // positions 1..leftBound fall off left

        // Find smallest R such that golem starting at R falls off right
        lo = 1; hi = N + 1;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (simulate(mid) == 1) hi = mid;
            else lo = mid + 1;
        }
        int rightBound = lo; // positions rightBound..N fall off right

        int survivors = Math.max(0, rightBound - leftBound - 1);
        System.out.println(survivors);
    }
}

