public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int N, Q;
    static char[] s;
    static char[] t, d;

    // returns true if the golem starting at pos falls off the left side
    static boolean fallsLeft(int pos) {
        int x = pos;
        for (int i = 0; i < Q; i++) {
            if (s[x] == t[i]) {
                if (d[i] == 'L') {
                    x--;
                    if (x < 0) return true;
                } else {
                    x++;
                    if (x >= N) return false;
                }
            }
        }
        return false;
    }

    // returns true if the golem starting at pos falls off the right side
    static boolean fallsRight(int pos) {
        int x = pos;
        for (int i = 0; i < Q; i++) {
            if (s[x] == t[i]) {
                if (d[i] == 'L') {
                    x--;
                    if (x < 0) return false;
                } else {
                    x++;
                    if (x >= N) return true;
                }
            }
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        N = fs.nextInt();
        Q = fs.nextInt();
        s = fs.next().toCharArray();

        t = new char[Q];
        d = new char[Q];
        for (int i = 0; i < Q; i++) {
            t[i] = fs.next().charAt(0);
            d[i] = fs.next().charAt(0);
        }

        // Find how many positions from the left fall off left
        int low = -1, high = N; // last true / first false
        while (high - low > 1) {
            int mid = (low + high) >>> 1;
            if (fallsLeft(mid)) low = mid;
            else high = mid;
        }
        int leftGone = low + 1;

        // Find how many positions from the right fall off right
        low = -1;
        high = N;
        while (high - low > 1) {
            int mid = (low + high) >>> 1;
            if (fallsRight(mid)) high = mid;
            else low = mid;
        }
        int rightStart = high;
        int rightGone = N - rightStart;

        int ans = N - leftGone - rightGone;
        if (ans < 0) ans = 0;

        System.out.println(ans);
    }
}

